from types import SimpleNamespace

import dspy
import pydantic


class FakeResp(dict):
    cache_hit = False

    def __init__(self, text):
        choice = SimpleNamespace(message=SimpleNamespace(content=text, tool_calls=None), finish_reason="stop")
        super().__init__({"choices": [choice]})
        self.choices = [choice]
        self.usage = {"prompt_tokens": 1, "completion_tokens": 1, "total_tokens": 2}
        self.model = "custom/offline"


class CaptureLM(dspy.BaseLM):
    def __init__(self, support_response_format, support_schema):
        super().__init__("custom/offline", "chat", 0.0, 1000, False)
        self._support_response_format = support_response_format
        self._support_schema = support_schema
        self.calls = []

    @property
    def supported_params(self):
        return {"response_format"} if self._support_response_format else set()

    @property
    def supports_response_schema(self):
        return self._support_schema

    def forward(self, prompt=None, messages=None, **kwargs):
        self.calls.append({"prompt": prompt, "messages": messages, **kwargs})
        return FakeResp('{"answer": "Paris"}')

    async def aforward(self, prompt=None, messages=None, **kwargs):
        return self.forward(prompt=prompt, messages=messages, **kwargs)


class QASignature(dspy.Signature):
    question: str = dspy.InputField()
    answer: str = dspy.OutputField()


program = dspy.Predict(QASignature)
adapter = dspy.JSONAdapter()
structured_lm = CaptureLM(True, True)
json_mode_lm = CaptureLM(True, False)
plain_lm = CaptureLM(False, False)

with dspy.context(lm=structured_lm, adapter=adapter):
    assert program(question="What is the capital of France?").answer == "Paris"

with dspy.context(lm=json_mode_lm, adapter=adapter):
    assert program(question="What is the capital of France?").answer == "Paris"

with dspy.context(lm=plain_lm, adapter=adapter):
    assert program(question="What is the capital of France?").answer == "Paris"

structured_rf = structured_lm.calls[0]["response_format"]
json_mode_rf = json_mode_lm.calls[0]["response_format"]
plain_has_rf = "response_format" in plain_lm.calls[0]

assert issubclass(structured_rf, pydantic.BaseModel)
assert json_mode_rf == {"type": "json_object"}
assert not plain_has_rf

print(
    {
        "structured_response_format_type": structured_rf.__name__,
        "json_mode_response_format": json_mode_rf,
        "plain_has_response_format": plain_has_rf,
    }
)
