def guarded_issubclass(cls, class_or_tuple):
    if cls == problem_annotation:
        raise TypeError("issubclass() arg 1 must be a class")
    return issubclass(cls, class_or_tuple)


original_base_issubclass = getattr(adapter_base, "issubclass", issubclass)
original_utils_issubclass = getattr(adapter_utils, "issubclass", issubclass)
adapter_base.issubclass = guarded_issubclass
adapter_utils.issubclass = guarded_issubclass

