import dspy
from dspy.utils.dummies import DummyLM


class FallbackLM(DummyLM):
    def __init__(self):
        super().__init__([{"answer": "worked"}], adapter=dspy.JSONAdapter())
        self.response_formats = []

    @property
    def supported_params(self):
        return {"response_format"}

    @property
    def supports_response_schema(self):
        return True

    def forward(self, prompt=None, messages=None, **kwargs):
        self.response_formats.append(kwargs.get("response_format"))
        if len(self.response_formats) == 1:
            raise RuntimeError("structured output failed")
        return super().forward(prompt=prompt, messages=messages, **kwargs)


lm = FallbackLM()
program = dspy.Predict("question -> answer")
with dspy.context(lm=lm, adapter=dspy.JSONAdapter()):
    result = program(question="dummy question")

assert len(lm.response_formats) == 2
first = lm.response_formats[0]
second = lm.response_formats[1]
assert hasattr(first, "model_json_schema")
assert second == {"type": "json_object"}
assert result.answer == "worked"
print("first_response_format_type:", type(first).__name__)
print("second_response_format:", second)
print("answer:", result.answer)
